update.foreach:
update
    safety_field_manage
set
    field_sort = #{item.fieldSort}
where
    id = #{item.id}

mapper.select:
select f2.id, f2.field_name, f2.field_sort, f2.field_type, f2.create_time, f2.update_time,
        f2.delete_falg, f2.parent_id, f2.field_code, f2.field_level
  from safety_field_manage f1,safety_field_manage f2 where f1.parent_id = f2.id and f1.id = #{filedId}
